def word_frequency(text: str) -> dict[str, int]:
    from string import punctuation
    freq: dict[str, int] = {}
    for word in text.split():
        word = word.strip(punctuation).lower()
        if word:
            freq[word] = freq.get(word, 0) + 1
    return freq
